# WAR ARENA - Auth/Identity Layer (Telegram initData) - Installer
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-auth.ps1
# Additive only. Zero new dependencies (node:crypto). Files Base64-encoded.
$ErrorActionPreference = "Stop"
Write-Host "WAR - Auth/Identity installer (Telegram initData verification)" -ForegroundColor Cyan
function Write-B64([string]$Path, [string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path, [System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/auth/authMiddleware.ts" ""
Write-B64 "src/auth/identityMapper.ts" ""
Write-B64 "src/auth/index.ts" ""
Write-B64 "src/auth/telegramAuth.ts" ""
Write-B64 "tests/architecture/authBoundaries.test.ts" ""
Write-B64 "tests/unit/auth.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "root typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Auth layer installed." -ForegroundColor Green
Write-Host "Expected: 854 passed + 1 skipped, 405 guards. No new npm deps." -ForegroundColor Yellow
